#!/bin/sh
package_menu(){ while :; do c=$(ui_menu Packages "Package manager: $PKG_MGR" update 'Refresh package metadata' upgrade 'Upgrade installed packages' install 'Install packages' remove 'Remove packages' search 'Search package names' native 'Native configuration adapter' bundles 'Install software bundles' clean 'Clean caches') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in update) run_capture Update pkg_update;; upgrade) run_capture Upgrade pkg_upgrade;; install) p=$(ui_input Install 'Space-separated package names:' '') || continue; [ -n "$p" ] && run_capture Install pkg_install $p;; remove) p=$(ui_input Remove 'Space-separated package names:' '') || continue; [ -n "$p" ] && run_capture Remove pkg_remove $p;; search) q=$(ui_input Search 'Search term:' '') || continue; package_search "$q";; native) case $PKG_MGR in apt) apt_menu;; apk) apk_menu;; pacman) pacman_menu;; *) ui_msg Native 'No specialized adapter loaded.';; esac;; bundles) bundle_menu;; clean) package_clean;; esac; done; }
package_search(){ case $PKG_MGR in apt) apt-cache search "$1";; apk) apk search -v "$1";; pacman) pacman -Ss "$1";; dnf|yum) "$PKG_MGR" search "$1";; xbps) xbps-query -Rs "$1";; emerge) emerge -s "$1";; esac >"$TMP_DIR/search" 2>&1; ui_text Search "$(head -n 150 "$TMP_DIR/search")"; }
package_clean(){ case $PKG_MGR in apt) run_capture Clean as_root apt-get clean;; apk) run_capture Clean as_root rm -f /var/cache/apk/*.apk;; pacman) run_capture Clean as_root pacman -Sc;; dnf) run_capture Clean as_root dnf clean all;; yum) run_capture Clean as_root yum clean all;; xbps) run_capture Clean as_root xbps-remove -O;; esac; }
bundle_menu(){ c=$(ui_menu Bundles 'Install a curated bundle.' base 'Core utilities' dev 'Development tools' network 'Network diagnostics' terminal 'Terminal tools' editors 'Editors' all 'All recommended tools') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in base) p='bash bash-completion curl wget rsync file less tar gzip xz';; dev) p='git make cmake ninja gcc gdb strace python3';; network) p='openssh iproute2 iputils bind-tools netcat-openbsd'; [ "$PKG_MGR" = apt ] && p='openssh-client openssh-server iproute2 iputils-ping dnsutils netcat-openbsd';; terminal) p='dialog tmux screen htop tree jq fzf';; editors) p='nano vim neovim micro';; all) p='bash curl wget rsync git make cmake ninja gcc gdb strace python3 openssh tmux screen htop tree jq fzf nano vim';; esac; run_capture Bundle pkg_install $p; }
